@pytest.mark.parametrize("name,override", [("X-Mode","one"),("x-MODE","two"),("X-mode","three")])
def test_request_records(name, override):
    seen=[]
    def handle(request):
        seen.append((request.headers["x-mode"],request.headers["x-keep"],request.content))
        return httpx.Response(200,json={"ok":True})
    with httpx.Client(transport=httpx.MockTransport(handle),headers={"x-mode":"default","x-keep":"yes"},trust_env=False) as client:
        client.post("https://example.test/submit",headers={name:override},json={"value":override})
        client.get("https://example.test/after")
        assert seen[0] == (override,"yes",json.dumps({"value":override},separators=(",",":")).encode())
        assert seen[1] == ("default","yes",b"")
        assert client.headers["x-mode"] == "default"

@pytest.mark.parametrize("mode,expected",[("elapsed","timeout"),("native","timeout"),("failure","error")])
async def test_second_provider_records(mode,expected):
    calls=[]
    class First:
        name,model,locality="primary","fixture","local"
        async def infer(self,question):
            calls.append("primary")
            if mode == "elapsed": await asyncio.sleep(60)
            if mode == "native": raise TimeoutError("provider deadline")
            raise ValueError("provider failed")
    def recover(question):
        calls.append("fallback")
        return {"a":0,"b":1}
    engine=Decilist([First(),FunctionProvider(recover,name="fallback")],policy=Policy(timeout_ms=10))
    result=await engine.decide(Choose(state="observed",instructions="Select",options={"a":"A","b":"B"}))
    assert result.value == "b" and result.provider == "fallback"
    assert calls == ["primary","fallback"]
    assert [(a.provider,a.outcome) for a in result.attempts] == [("primary",expected),("fallback","accepted")]
    assert json.loads(result.model_dump_json())["attempts"][0]["outcome"] == expected

@property
def headers(self) -> Headers:
    """
    HTTP headers to include when sending requests.
    """
    return self._headers

@headers.setter
def headers(self, headers: HeaderTypes) -> None:
    client_headers = Headers(
        {
            b"Accept": b"*[EXTERNAL]/*",
            b"Accept-Encoding": ACCEPT_ENCODING.encode("ascii"),
            b"Connection": b"keep-alive",
            b"User-Agent": USER_AGENT.encode("ascii"),
        }
    )
    client_headers.update(headers)
    self._headers = client_headers

def update(self, headers: HeaderTypes | None = None) -> None:  # type: ignore
    headers = Headers(headers)
    for key in headers.keys():
        if key in self:
            self.pop(key)
    self._list.extend(headers._list)
